// Original, locally synthesised soundtrack and effects. No audio downloads or recordings.
const GameAudio={ctx:null,musicBus:null,effectsBus:null,unlocked:false,timer:null,step:0,nextBeat:0,duckUntil:0,lastEffect:{},failed:false,
  ensure(){try{if(!this.ctx){const Context=window.AudioContext||window.webkitAudioContext;if(!Context){this.failed=true;this.status();return false}this.ctx=new Context();this.ctx.onstatechange=()=>this.status();const master=this.ctx.createGain(),limiter=this.ctx.createDynamicsCompressor();master.gain.value=.65;limiter.threshold.value=-18;limiter.knee.value=12;limiter.ratio.value=5;limiter.attack.value=.005;limiter.release.value=.15;this.musicBus=this.ctx.createGain();this.effectsBus=this.ctx.createGain();this.musicBus.connect(limiter);this.effectsBus.connect(limiter);limiter.connect(master);master.connect(this.ctx.destination)}if(this.ctx.state==='suspended')this.ctx.resume().catch(()=>{});this.unlocked=true;this.apply();this.start();this.status();return true}catch{this.failed=true;this.status();return false}},
  status(){const label=document.querySelector('#audio-status');if(label)label.textContent=this.failed?'Audio is unavailable in this browser.':!this.unlocked?'Tap a game button to enable audio.':!profile.music&&!profile.sound?'Audio is muted.':this.ctx?.state==='running'?'Audio is ready.':'Tap a game button to resume audio.'},
  apply(){if(!this.ctx)return;const now=this.ctx.currentTime,hidden=document.hidden;const music=profile.music&&!hidden?profile.musicVolume:0,effects=profile.sound&&!hidden?profile.effectsVolume:0;this.musicBus.gain.setTargetAtTime(music,now,.04);this.effectsBus.gain.setTargetAtTime(effects,now,.015);this.status()},
  voice(freq,time,length,volume,type='sine',bus=this.effectsBus,endFreq=null){if(!this.ctx||!bus||volume<=0)return;const o=this.ctx.createOscillator(),gain=this.ctx.createGain();o.type=type;o.frequency.setValueAtTime(Math.max(20,freq),time);if(endFreq)o.frequency.exponentialRampToValueAtTime(Math.max(20,endFreq),time+length);gain.gain.setValueAtTime(.0001,time);gain.gain.exponentialRampToValueAtTime(Math.max(.0002,volume),time+.008);gain.gain.exponentialRampToValueAtTime(.0001,time+length);o.connect(gain);gain.connect(bus);o.start(time);o.stop(time+length+.02);o.onended=()=>{o.disconnect();gain.disconnect()}},
  noise(time,length,volume,cutoff=1800,bus=this.effectsBus){if(!this.ctx||!bus)return;const size=Math.ceil(this.ctx.sampleRate*length),buffer=this.ctx.createBuffer(1,size,this.ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<size;i++)data[i]=Math.random()*2-1;const source=this.ctx.createBufferSource(),filter=this.ctx.createBiquadFilter(),gain=this.ctx.createGain();source.buffer=buffer;filter.type='highpass';filter.frequency.value=cutoff;gain.gain.setValueAtTime(Math.max(.0002,volume),time);gain.gain.exponentialRampToValueAtTime(.0001,time+length);source.connect(filter);filter.connect(gain);gain.connect(bus);source.start(time);source.stop(time+length);source.onended=()=>{source.disconnect();filter.disconnect();gain.disconnect()}},
  start(){if(this.timer||!this.unlocked)return;this.nextBeat=this.ctx.currentTime+.06;this.timer=setInterval(()=>this.schedule(),80);this.schedule()},
  stop(){if(this.timer){clearInterval(this.timer);this.timer=null}if(this.musicBus)this.musicBus.gain.setTargetAtTime(0,this.ctx.currentTime,.02)},
  schedule(){if(!this.ctx||document.hidden||!profile.music||this.ctx.state!=='running')return;const now=this.ctx.currentTime;if(this.nextBeat<now-.25)this.nextBeat=now+.03;let count=0;while(this.nextBeat<now+.2&&count++<12){this.musicStep(this.step++,this.nextBeat);this.nextBeat+=60/(game&&!game.paused?(game.boss&&game.boss.hp>0?(game.boss.phase===2?148:142):132):112)/2}},
  musicStep(step,time){
    const battle=!!game&&!game.paused,boss=battle&&game.boss&&game.boss.hp>0,reading=modal.open,track=boss?'Scrambler Showdown':battle?'Neon Sprint':'Quest Rally';if(this.trackName!==track){this.trackName=track;const label=document.querySelector('#music-track');if(label)label.textContent=track}
    const bar=Math.floor(step/8)%8,beat=step%8,roots=boss?[50,46,48,45,50,46,43,45]:[48,55,57,53,48,55,53,55],root=roots[bar],shift=!boss&&battle&&game.map?.name==='Ember Canyon'?-2:0,midi=n=>440*Math.pow(2,(n-69)/12),duck=time<this.duckUntil ? .1 : (reading ? .34 : 1),level=duck*(battle?1:.82),bus=this.musicBus;
    const rally=[76,-1,79,79,81,79,76,74,72,-1,74,76,79,-1,76,74,76,-1,79,81,84,81,79,76,74,-1,76,74,72,-1,72,-1,76,79,81,79,76,74,76,-1,74,76,79,83,81,79,76,74,76,79,81,84,81,79,76,74,74,-1,76,74,72,74,72,-1];
    const showdown=[77,-1,81,77,84,81,77,76,74,-1,77,79,81,-1,79,77,79,76,72,76,79,81,79,76,73,-1,76,79,81,-1,79,76,77,81,84,81,86,84,81,77,77,-1,81,84,86,84,81,77,79,76,72,76,79,81,84,79,81,-1,79,76,74,76,74,-1];
    const note=(boss?showdown:rally)[step%64]+shift,playLead=battle||!reading||beat%2===0;
    if((boss?showdown:rally)[step%64]>0&&playLead){this.voice(midi(note),time,beat%4===0?.24:.16,.14*level,'triangle',bus);this.voice(midi(note-12),time,.13,(boss ? .045 : .028)*level,boss?'sawtooth':'square',bus);if(battle&&!boss&&game.map?.name==='Moonlight Circuit'&&beat%2===1)this.voice(midi(note+7),time+.105,.09,.035*level,'sine',bus)}
    if([0,3,4,6].includes(beat)||(boss&&beat===7)){const bass=root-12+shift+(beat===3||beat===6?12:0);this.voice(midi(bass),time,.22,.26*level,'triangle',bus)}
    if(beat===0||beat===4){const minor=boss||root===57;for(const interval of [0,minor?3:4,7]){this.voice(midi(root+interval+shift),time,.36,.042*level,'triangle',bus);if(battle)this.voice(midi(root+interval+12+shift),time+.025,.18,.018*level,'sawtooth',bus)}}
    if(!reading){if(beat===0||beat===4||(battle&&beat===3)||(boss&&beat===7))this.voice(145,time,.16,.34*level,'sine',bus,42);if(beat===2||beat===6){this.noise(time,.1,.1*level,1000,bus);this.voice(185,time,.065,.045*level,'triangle',bus,110)}this.noise(time,beat===7?.09:.032,(beat%2?.035:.05)*level,6500,bus);if(bar===7&&beat===7){this.noise(time+.11,.04,.07*level,1500,bus);this.voice(200,time+.11,.05,.08*level,'triangle',bus,120)}}
  },
  effect(name){if(!this.unlocked||!this.ctx||!profile.sound||document.hidden)return;const t=this.ctx.currentTime+.01;if(t-(this.lastEffect[name]??-100)<({hit:.045,pickup:.07,enemy:.12}[name]||.035))return;this.lastEffect[name]=t;const v=(f,d=.1,a=.16,type='sine',end=null,offset=0)=>this.voice(f,t+offset,d,a,type,this.effectsBus,end),seq=(notes,d=.1,a=.16)=>notes.forEach((f,i)=>v(f,d,a,'triangle',null,i*(d*.8)));
    switch(name){case'click':v(1300,.025,.055);break;case'shoot':v(1000,.09,.12,'triangle',190);break;case'hit':v(230,.065,.13,'triangle',80);this.noise(t,.045,.045,1100);break;case'hurt':seq([180,125],.14,.2);break;case'pickup':seq([784,1175],.085,.14);break;case'dash':this.noise(t,.15,.11,1600);v(340,.13,.09,'sine',850);break;case'super':v(100,.4,.25,'sine',40);seq([392,587,784],.16,.18);this.noise(t,.22,.07,700);break;case'wave':seq([392,494,587,784],.13,.15);break;case'win':seq([523,659,784,1047,1319],.2,.2);break;case'finish':seq([392,330,262],.19,.16);break;case'correct':seq([523,659,784],.1,.16);break;case'wrong':seq([330,294],.16,.1);break;case'unlock':seq([659,784,988,1319],.16,.18);break;case'warning':seq([440,554],.13,.12);break;case'enemy':v(620,.12,.055,'sine',380);break;case'defeat':v(210,.14,.1,'triangle',65);this.noise(t,.07,.055,750);break}
  },
  example(notes,duration=.35){if(!profile.sound||!this.ensure())return;const t=this.ctx.currentTime+.04;this.duckUntil=t+notes.length*(duration+.08)+.25;notes.forEach((f,i)=>this.voice(f,t+i*(duration+.08),duration,.2,'sine'))}
};
function audioButtons(){return `<div class="audio-quick"><button data-audio="music" aria-pressed="${!!profile.music}" aria-label="${profile.music?'Mute':'Enable'} background music">${profile.music?'♫ Music on':'♫ Music off'}</button><button data-audio="sound" aria-pressed="${!!profile.sound}" aria-label="${profile.sound?'Mute':'Enable'} sound effects">${profile.sound?'♪ Sound on':'♪ Sound off'}</button></div>`}
function refreshAudioUI(){document.querySelectorAll('[data-audio]').forEach(b=>{const music=b.dataset.audio==='music',enabled=!!profile[music?'music':'sound'];b.textContent=(music?'♫ Music ':'♪ Sound ')+(enabled?'on':'off');b.setAttribute('aria-pressed',String(enabled));b.setAttribute('aria-label',(enabled?'Mute':'Enable')+(music?' background music':' sound effects'))});document.querySelectorAll('[data-audio-volume]').forEach(input=>{input.value=Math.round(profile[input.dataset.audioVolume]*100)});GameAudio.apply()}
function initAudio(){profile.music??=profile.sound!==false;profile.musicVolume=Math.max(0,Math.min(1,Number.isFinite(profile.musicVolume)?profile.musicVolume:.24));profile.effectsVolume=Math.max(0,Math.min(1,Number.isFinite(profile.effectsVolume)?profile.effectsVolume:.65));const host=document.querySelector('#audio-settings');if(host)host.innerHTML=`<details class="audio-settings"><summary aria-label="Music and sound settings">♫ Audio</summary><div class="audio-panel"><h3>Make some noise.</h3>${audioButtons()}<label>Music volume<input aria-label="Music volume" data-audio-volume="musicVolume" type="range" min="0" max="100" value="${Math.round(profile.musicVolume*100)}"></label><label>Sound volume<input aria-label="Sound effects volume" data-audio-volume="effectsVolume" type="range" min="0" max="100" value="${Math.round(profile.effectsVolume*100)}"></label><button class="audio-test" data-audio-preview="true">♪ Test sound</button><p id="audio-status" role="status">Tap a game button to enable audio.</p><p class="now-playing">NOW PLAYING <strong id="music-track">Quest Rally</strong></p><p>Original adaptive soundtrack and effects.<br>Settings save on this device.</p></div></details>`;
  document.addEventListener('pointerdown',()=>GameAudio.ensure(),{capture:true});document.addEventListener('keydown',e=>{if(!e.repeat)GameAudio.ensure()},{capture:true});
  document.addEventListener('click',e=>{if(e.target.closest('[data-audio-preview]')){GameAudio.ensure();if(profile.sound&&profile.effectsVolume>0)GameAudio.effect('win');else toast('Turn on Sound and raise its volume to test effects.');return}const b=e.target.closest('[data-audio]');if(b){GameAudio.ensure();const key=b.dataset.audio;profile[key]=!profile[key];save();refreshAudioUI();return}if(e.target.closest('button'))GameAudio.effect('click')});
  document.addEventListener('input',e=>{const key=e.target.dataset?.audioVolume;if(!key)return;profile[key]=Number(e.target.value)/100;save();refreshAudioUI()});
  document.addEventListener('visibilitychange',()=>{if(document.hidden){GameAudio.stop();GameAudio.ctx?.suspend().catch(()=>{})}else if(GameAudio.unlocked)GameAudio.ensure()});
  let audioPausedGame=null;const details=document.querySelector('.audio-settings');if(details)details.addEventListener('toggle',()=>{if(details.open){if(game&&!game.paused){audioPausedGame=game;game.paused=true;resetControls()}}else{if(audioPausedGame&&game===audioPausedGame&&!modal.open){game.paused=false;last=performance.now()}audioPausedGame=null}});
  document.addEventListener('pointerdown',e=>{if(details?.open&&!details.contains(e.target))details.open=false});refreshAudioUI()
}
